INSERT INTO public.source_pages (import_run_id,book_id,source_page,page_kind,raw_transcription,chapter_heading,topic_heading,confidence,extraction_method,model_name,notes,review_metadata) SELECT (SELECT id FROM public.import_runs WHERE pipeline_version='vision-quality-gated-batch-0554-0558-v1' ORDER BY started_at DESC LIMIT 1),b.id,556,'educational'::page_kind,'ইসরাইল

ইতিহাসে ফিলিস্তিন নামে পরিচিত ভূ-ভাগের অংশ বিশেষ নিয়ে ইসরাইল রাষ্ট্র। এটি ইহুদিদের আবাসভূমি যা আরবদের কাছ থেকে জোরপূর্বক দখল করা হয়েছে। মুসলমান, ইহুদী ও খ্রিস্টান এই তিন ধর্মানুষ্ঠানদের কাছে পবিত্রভূমি জেরুজালেম। ইহুদিদের আবাসস্থল জুহাদ খ্রিস্টপূর্ব ৫৮৬ সালে বাবিলনিয়দের দ্বারা আক্রান্ত হলে তারা পৃথিবীর বিভিন্ন দেশে ছড়িয়ে পড়ে। উনিশ শতকে পৃথিবীতে ছড়িয়ে থাকা ইহুদিরা রাষ্ট্র প্রতিষ্ঠার জন্য আন্দোলন শুরু করেন এবং ফিলিস্তিনে একত্রিত হন। ব্রিটিশ ও মার্কিন মদদপুষ্ট হয়ে ১৯৪৮ সালে ইহুদিরা আরব ভূখাতে রাষ্ট্র প্রতিষ্ঠা করে। তেল আবিব, হাইফা, যোহান, বীরসেবা দেশের উল্লেখযোগ্য শহর।

বেলফোর ঘোষণা

১৯১৭ সালে ব্রিটিশ ইহুদী সম্প্রদায়ের নেতা ব্যারন রথচাইল্ডের কাছে তৎকালীন ব্রিটিশ পররাষ্ট্র সচিব আর্থার জেমস বেলফোরের লেখা একটি চিঠি, যা ইতিহাসে ''বেলফোর ঘোষণা'' নামে পরিচিত। এতে ফিলিস্তিনে ইহুদিদের জন্য একটি জাতি রাষ্ট্র প্রতিষ্ঠার অঙ্গীকার করা হয়। চিঠির মূল কপিটি ব্রিটিশ লাইব্রেরীতে সংরক্ষিত রয়েছে।

♦ বেলফোর ঘোষণার মূল প্রতিপাদ্য- ইহুদিদের জন্য একটি জাতি রাষ্ট্র গঠন।
♦ বেলফোর ঘোষণা করা হয়- ১৯১৭ সালে।
♦ ইহুদিদের চোখে ফিলিস্তিনীরা তাদের মাতৃভূমি হারায়- ১৯৪৮ সালে।
♦ ফিলিস্তিনিদের মাতৃভূমিতে ইসরাইল রাষ্ট্র প্রতিষ্ঠিত হয়- ১৪ মে, ১৯৪৮ সালে।

বেসিক তথ্য

♦ ইসরাইলের প্রধান ভাষা- হিব্রু ও আরবি
♦ মুদ্রার নাম- শেকেল
♦ আইনসভা হল- নেসেট (Knesset)
♦ রাজধানীর নাম- তেল আবিব; (দাবি করে জেরুজালেমকে)

ইসরাইলের মুদ্রা শেকেল

ইসরাইলকে স্বীকৃতি

♦ স্বীকৃতি প্রদানকারী প্রথম দেশ- মার্কিন যুক্তরাষ্ট্র; ১৪ মে, ১৯৪৮ ।
♦ স্বীকৃতি প্রদানকারী দ্বিতীয় দেশ- তৎকালীন সোভিয়েত ইউনিয়ন ।
♦ স্বীকৃতি প্রদানকারী প্রথম মুসলিম দেশ- তুরস্ক; ২৮ মার্চ, ১৯৪৯ ।
♦ স্বীকৃতি প্রদানকারী প্রথম আরব দেশ- মিশর; ২৬ মার্চ, ১৯৭৯ ।

