INSERT INTO public.fact_verifications (source_page,entity_type,entity_id,claim_text,normalized_claim,verification_status,confidence,verification_sources,audit_note) SELECT 554,'fact',(SELECT id FROM public.gk_facts WHERE canonical_hash='d02ca9cf9a4878b105c9382580573252cc494de5386feae0363601c051192488' LIMIT 1),'৯ সেপ্টেম্বর ১৯৯৩-এর চিঠিতে PLO ইসরাইলের শান্তি ও নিরাপত্তার মধ্যে অস্তিত্বের অধিকার স্বীকার করে; ইসরাইল PLO-কে Palestinian people-এর প্রতিনিধি হিসেবে স্বীকৃতি দেয়।',NULL,'verified','high'::confidence_level,'["https://www.un.org/unispal/document/auto-insert-205528/"]'::jsonb,'Direct official corroboration is listed in the batch verification ledger.' WHERE NOT EXISTS (SELECT 1 FROM public.fact_verifications v WHERE v.entity_type='fact' AND v.entity_id=(SELECT id FROM public.gk_facts WHERE canonical_hash='d02ca9cf9a4878b105c9382580573252cc494de5386feae0363601c051192488' LIMIT 1) AND v.claim_text='৯ সেপ্টেম্বর ১৯৯৩-এর চিঠিতে PLO ইসরাইলের শান্তি ও নিরাপত্তার মধ্যে অস্তিত্বের অধিকার স্বীকার করে; ইসরাইল PLO-কে Palestinian people-এর প্রতিনিধি হিসেবে স্বীকৃতি দেয়।');
